#!/bin/bash
# Pack the input data that is not in git into solar_data.zip (unzip it in the repo root).
# Contents: 30 cm imagery, both merged LiDAR tiles (2017, 2025), OSM extract, TAMU GIS layers,
# TAMU reference documents. Everything under data/interim and outputs is regenerated by run_all.sh.
set -euo pipefail
cd "$(dirname "$0")"
rm -f solar_data.zip
zip -r -0 solar_data.zip \
  tamu_land_resources/tif/merged_tamu_esri_30cm.tif \
  tamu_land_resources/laz/merged_tamu.laz \
  tamu_land_resources/laz/merged_tamu_2025.laz \
  tamu_land_resources/osm/merged_tamu_osm.gpkg \
  data/raw/tamu_fcor.gpkg \
  data/raw/tamu_fcor_download.log \
  data/raw/tamu_docs/*.pdf
ls -lh solar_data.zip
